              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="text-center mb-6 pt-4"
            >
              <h2 className="text-xl md:text-2xl font-bold text-white mb-2">{title}</h2>
            </motion.div>

            {showPopup ? (
              <div className="text-center py-8">
                <motion.div
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
