import { useState, useEffect, useRef } from "react";
import { FaUser, FaClock } from "react-icons/fa";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import logo from "@/app/assets/icons/logo.png";
import { useRouter, usePathname } from "next/navigation"
import InternationalPhoneInput, {
  getInternationalPhoneValue,
  isValidInternationalPhone,
} from "./InternationalPhoneInput";
import { submitLead, leadStorage, loadLeadCaptcha, renderLeadCaptcha, resetLeadCaptcha } from "@/lib/lead-client";


export default function Popup({
  onClose,
  title = "Book Your Plot Now",
  thankYouTitle = "Thank You!",
  thankYouMessage = "Your request has been submitted successfully.",
  source = "Dholera Insider",
}) {
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({ fullName: "", phone: "" });
  const [showFormPopup, setShowFormPopup] = useState(true);
  const [showSubmissionSuccess, setShowSubmissionSuccess] = useState(false);
  const [submissionCount, setSubmissionCount] = useState(0);
  const [lastSubmissionTime, setLastSubmissionTime] = useState(0);
  const [errorMessage, setErrorMessage] = useState("");
  const [recaptchaLoaded, setRecaptchaLoaded] = useState(false);
  const [showThankYou, setShowThankYou] = useState(false);
  const recaptchaRef = useRef(null);
  const submitLock = useRef(false);
  const requestLock = useRef(false);
  const latestSuccess = useRef(null);
  const mounted = useRef(true);
  const closeTimer = useRef(null);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; clearTimeout(closeTimer.current); }; }, []);
  const siteKey = process.env.NEXT_PUBLIC_RECAPTCHA_SITE_KEY;
  const router = useRouter();
  const pathname = usePathname();
  const [showForm, setShowForm] = useState(false);

  const [timeLeft, setTimeLeft] = useState(1800);

  useEffect(() => {
    let timer;

    if (showForm) {
      setTimeLeft(1800);

      timer = setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            clearInterval(timer);
            return 0;
          }
          return prev - 1;
        });
      }, 5000);
    }

    return () => clearInterval(timer); // Cleanup
  }, [showForm]);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60)
      .toString()
      .padStart(2, "0");
    const secs = (seconds % 60).toString().padStart(2, "0");
    return `${mins}:${secs}`;
  };

  const [wasTriggered, setWasTriggered] = useState(false);

  // Parse title to extract price and time info
  const parseTitle = (title) => {
    const priceMatch = title.match(/₹([0-9,]+)/);
    const timeMatch = title.match(/(\d+:\d+:\d+)/);
    const price = priceMatch ? `₹${priceMatch[1]}` : "₹9250";
    const timeLeft = timeMatch ? timeMatch[1] : null;

    return {
      price,
      timeLeft,
      mainText: "For This WEEK",
      subText: ""
    };
  };

  const titleInfo = parseTitle(title);

  useEffect(() => {
    setShowFormPopup(true);
    setWasTriggered(true);
  }, []);
  // Handle close function
  const handleClose = () => {
    setShowFormPopup(false);
    if (onClose && typeof onClose === 'function') {
      onClose();
    }
  };

  useEffect(() => {
    // Load localStorage data
    if (typeof window !== "undefined") {
      setSubmissionCount(
        parseInt(leadStorage.getItem("formSubmissionCount") || "0", 10)
      );
      setLastSubmissionTime(
        parseInt(leadStorage.getItem("lastSubmissionTime") || "0", 10)
      );
    }

    // Load reCAPTCHA script
    const loadRecaptcha = () => {
    loadLeadCaptcha().then(() => setRecaptchaLoaded(true)).catch((error) => {
      setRecaptchaLoaded(false);
      setErrorMessage(error.message);
    });
  };

    loadRecaptcha();

    // Handle Escape key press
    const handleEscapeKey = (event) => {
      if (event.key === 'Escape') {
        handleClose();
      }
    };

    document.addEventListener('keydown', handleEscapeKey);

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({ ...prevData, [name]: value }));
    setErrorMessage("");
  };

  const validateForm = () => {
    if (!formData.fullName || !formData.phone) {
      setErrorMessage("Please fill in all fields");
      return false;
    }

    if (!isValidInternationalPhone(formData.phone)) {
      setErrorMessage("Please enter a valid international phone number");
      return false;
    }

    const now = Date.now();
    const hoursPassed = (now - lastSubmissionTime) / (1000 * 60 * 60);

    if (hoursPassed >= 24) {
      setSubmissionCount(0);
      leadStorage.setItem("formSubmissionCount", "0");
      leadStorage.setItem("lastSubmissionTime", now.toString());
    } else if (submissionCount >= 3) {
      setErrorMessage(
        "You have reached the maximum submission limit. Try again after 24 hours."
      );
      return false;
    }

    return true;
  };

  const onRecaptchaSuccess = async (token) => {
    if (!mounted.current) return;
    if (requestLock.current) return;
    requestLock.current = true;
    try {
      const now = Date.now();

      const response = await submitLead(
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",

          },
          body: JSON.stringify({
            fields: {
              name: formData.fullName,
              phone: getInternationalPhoneValue(formData.phone),
              source: "Dholera Insider",
            },
            source: "Dholera Insider",
            tags: ["Dholera Investment", "Website Lead", "BookMyAssets"],
            recaptchaToken: token,
          }),
        }
      );
      if (!mounted.current) return;

      if (response.ok) {
        setFormData({ fullName: "", phone: "" });
        setShowSubmissionSuccess(true);
        setSubmissionCount((prev) => {
          const newCount = prev + 1;
          leadStorage.setItem("formSubmissionCount", newCount.toString());
          leadStorage.setItem("lastSubmissionTime", now.toString());
          return newCount;
        });

        // Show thank you popup for 2 seconds
        setShowThankYou(true);
        closeTimer.current = setTimeout(() => {
          setShowThankYou(false);
          handleClose();
        }, 3000);


      } else {
        throw new Error("Error submitting form");
      }
    } catch (error) {
      console.error("Form submission error:", error);
      setErrorMessage(
        error.message || "Error submitting form. Please try again."
      );
    } finally {
      requestLock.current = false;
      setIsLoading(false);
      submitLock.current = false;
      if (window.grecaptcha && recaptchaRef.current) {
        resetLeadCaptcha(recaptchaRef.current);
      }
    }
  };
  useEffect(() => { latestSuccess.current = onRecaptchaSuccess; });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitLock.current) return;
    submitLock.current = true;
    setIsLoading(true);
    setErrorMessage("");
    try {
      await loadLeadCaptcha();
      if (!mounted.current) return;
      setRecaptchaLoaded(true);
    } catch (error) {
      setErrorMessage(error.message);
      setIsLoading(false);
      submitLock.current = false;
      return;
    }

    if (!validateForm()) {
      setIsLoading(false);
      submitLock.current = false;
      return;
    }

    // If reCAPTCHA is loaded, render it in the ref
    if (window.grecaptcha && Boolean(window.grecaptcha?.render)) {
      try {
        if (recaptchaRef.current && !recaptchaRef.current.innerHTML) {
          renderLeadCaptcha(recaptchaRef.current, {
            "expired-callback": () => { submitLock.current = false; setIsLoading(false); setErrorMessage("Verification expired. Please try again."); },
            "error-callback": () => { submitLock.current = false; setIsLoading(false); setErrorMessage("Verification failed to connect. Please try again."); },
            sitekey: siteKey,
            callback: (...args) => latestSuccess.current(...args),
            theme: "dark",
          });
        } else {
          resetLeadCaptcha(recaptchaRef.current);
        }
      } catch (error) {
        console.error("Error rendering reCAPTCHA:", error);
        setErrorMessage("Error with verification. Please try again.");
        setIsLoading(false);
      submitLock.current = false;
      }
    } else {
      setErrorMessage("reCAPTCHA not loaded. Please refresh and try again.");
      setIsLoading(false);
      submitLock.current = false;
    }
  };

  // Handle backdrop click
  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) {
      handleClose();
    }
  };

  // Prevent modal content click from closing modal
  const handleModalContentClick = (e) => {
    e.stopPropagation();
  };

  return (
    <>
      {/* Thank You Page */}
      <AnimatePresence>
        {showThankYou && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-[#051A3A] flex justify-center items-center z-[1001]"
          >
            <motion.div
              initial={{ scale: 0.5, y: 50 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.5, y: 50 }}
              className="text-center text-white px-8"
            >
              <motion.div
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ delay: 0.2 }}
                className="mb-6"
              >
                <div className="w-24 h-24 bg-[#F6C343] rounded-full flex items-center justify-center mx-auto">
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    className="h-12 w-12 text-[#051A3A]"
                    fill="none"
                    viewBox="0 0 24 24"
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={3}
                      d="M5 13l4 4L19 7"
                    />
                  </svg>
                </div>
              </motion.div>
              <motion.h1
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.4 }}
                className="text-4xl md:text-6xl font-bold mb-4"
              >
                {thankYouTitle}
              </motion.h1>
              <motion.p
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.6 }}
                className="text-lg md:text-xl"
              >
                {thankYouMessage}
              </motion.p>
              <motion.p
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.8 }}
                className="text-md opacity-80 mt-2"
              >
                Redirecting you back...
              </motion.p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Form Modal */}
      {showFormPopup && !showThankYou && (
        <div
          className="fixed inset-0 flex justify-center items-center bg-black bg-opacity-70 p-4 z-[1000]"
          onClick={handleBackdropClick}
          role="dialog"
          aria-modal="true"
          aria-label={title}
        >
          <motion.div
            id="contact-form-container"
            initial={{ scale: 0.9, y: 50, opacity: 0 }}
            animate={{ scale: 1, y: 0, opacity: 1 }}
            exit={{ scale: 0.9, y: 50, opacity: 0 }}
            className="bg-[#051A3A] rounded-2xl shadow-2xl max-w-lg w-full relative overflow-visible border border-[#F6C343]"
            onClick={handleModalContentClick}
          >


            {/* Header Section with Gradient Background */}
            <div className="bg-[#051A3A] text-white p-6 pb-8 pt-12 relative rounded-t-2xl">
              {/* Close Button */}
              <button
                type="button"
                onClick={handleClose}
                className="absolute top-4 right-4 text-white/80 hover:text-[#F6C343] focus:outline-none focus:ring-2 focus:ring-[#F6C343]/50 rounded-full p-2 transition-all duration-200 hover:bg-[#FDFCFA]/10 z-10"
                aria-label="Close form"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-5 w-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={2}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>

              {/* Content Section */}
              <div className="text-center">

                <h2 className="text-xl md:text-2xl font-bold mb-1 leading-tight text-[#F6C343]">
                {title}
                </h2>

                {titleInfo.timeLeft && (
                  <div className="bg-[#F6C343] text-[#051A3A] px-4 py-2 rounded-lg inline-flex items-center gap-2 font-bold mb-6">
                    <FaClock className="text-sm" />
                    {formatTime(timeLeft)} left!
                  </div>
                )}
              </div>
            </div>

            {/* Form Section */}
            <div className="p-6 bg-[#051A3A] rounded-b-2xl">
              {showSubmissionSuccess ? (
                <div className="text-center py-8">
                  <motion.div
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    className="mb-4 inline-block"
                  >
                    <div className="w-16 h-16 bg-[#F6C343] rounded-full flex items-center justify-center mx-auto">
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        className="h-10 w-10 text-[#051A3A]"
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M5 13l4 4L19 7"
                        />
                      </svg>
                    </div>
                  </motion.div>
                  <h3 className="text-2xl font-bold text-[#F6C343] mb-2">
                    Thank You!
                  </h3>
                  <p className="text-[#FDFCFA]/80">
                    Your request has been submitted successfully. We&apos;ll contact
                    you shortly.
                  </p>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-5">
                  {errorMessage && (
                    <motion.div role="alert"
                      initial={{ opacity: 0, y: -10 }}
                      animate={{ opacity: 1, y: 0 }}
                      className="rounded-lg border border-[#B42318] bg-[#B42318]/15 p-3 text-sm text-[#FDFCFA]"
                    >
                      {errorMessage}
                    </motion.div>
                  )}

                  <motion.div
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.4 }}
                    className="relative"
                  >
                    <FaUser className="absolute left-4 top-1/2 transform -translate-y-1/2 text-[#6C7484]" />
                    <input aria-label="Full name" maxLength={200} autoComplete="name"
                      name="fullName"
                      placeholder="Enter your full name"
                      value={formData.fullName}
                      onChange={handleChange}
                      required
                      className="w-full rounded-lg border border-[#2B364D] bg-[#FDFCFA] p-3 pl-12 text-[#162033] placeholder:text-[#6C7484] focus:outline-none focus:ring-2 focus:ring-[#F6C343]"
                    />
                  </motion.div>

                  <motion.div
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.5 }}
                    className="relative"
                  >
                    <InternationalPhoneInput
                      value={formData.phone}
                      onChange={(phone) => {
                        setFormData((prevData) => ({ ...prevData, phone }));
                        setErrorMessage("");
                      }}
                      inputProps={{
                        id: "phone",
                        name: "phone",
                        placeholder: "Enter phone number",
                      }}
                    />
                  </motion.div>

                  {/* reCAPTCHA container */}
                  <div className="flex justify-center">
                    <div ref={recaptchaRef}></div>
                  </div>

                  <motion.button
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.6 }}
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    type="submit"
                    id="popup"
                    disabled={isLoading}
                    className="w-full py-4 px-6 bg-[#F6C343] text-[#051A3A] rounded-lg hover:bg-[#FDFCFA] transition-all shadow-lg hover:shadow-[#F6C343]/25 font-bold text-lg disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                  >
                    {isLoading ? (
                      <>
                        <div className="w-5 h-5 border-2 border-[#051A3A]/30 border-t-[#051A3A] rounded-full animate-spin"></div>
                        Verifying...
                      </>
                    ) : recaptchaLoaded ? (
                      <>
                       Get A Call Back
                      </>
                    ) : (
                      "Loading..."
                    )}
                  </motion.button>

                  <p className="text-xs text-[#FDFCFA]/70 text-center">
                    We respect your privacy. Your details are safe with us.
                  </p>
                </form>
              )}
            </div>
          </motion.div>
        </div>
      )}
    </>
  );
}

import React, { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

export default function TestimonialsSection() {
  const [currentTestimonial, setCurrentTestimonial] = useState(0);
  const [direction, setDirection] = useState('right');

  const testimonials = [
    {
      name: "Kunal Kumar",
      location: "Noida, Uttar Pradesh",
      text: "I had been exploring investment opportunities around Dholera, and I'm glad I came across the team behind WestWyn County. They guided me with full clarity, from plot selection to legal documentation. What I liked most was how transparent and patient they were. WestWyn County feels like a smart, future-ready project, and I'm proud to be a part of it."
    },
    {
      name: "Gaurav Parmar",
      location: "Surat, Gujarat",
      text: "The team helped me understand everything about the Dholera region, future development, government approvals, town planning, everything. WestWyn County stood out because of its layout and the long-term appreciation potential. Their process was smooth and professional. I felt safe investing here."
    },
    {
      name: "Jaspreet Singh",
      location: "Ludhiana, Punjab",
      text: "I was looking for a clear-title plot with proper TP approval and genuine developer support. The team behind WestWyn County made it simple. From explaining the location benefits to arranging a site visit, they handled it all. The pricing was great too. I'm already planning to invest in a second plot!"
    },
    {
      name: "Satendra Dahiya",
      location: "Gurugram, Haryana",
      text: "What impressed me the most was how they explained every detail without any pressure to buy. I felt like I was working with experts, not salespeople. WestWyn County was well-planned, close to the activation zone, and still in my budget. I'm confident this will be a profitable long-term investment."
    },
    {
      name: "Alpa Batra",
      location: "Mumbai, Maharashtra",
      text: "I had looked at multiple projects before, but none matched the kind of service and clarity I got here. They answered all my questions, arranged the paperwork, and made the entire process smooth. WestWyn County gives me the peace of mind that my investment is secure and growing."
    }
  ];

  const nextTestimonial = () => {
    setDirection('right');
    setCurrentTestimonial((prev) => (prev + 1) % testimonials.length);
  };

  const prevTestimonial = () => {
    setDirection('left');
    setCurrentTestimonial((prev) => (prev - 1 + testimonials.length) % testimonials.length);
  };

  const goToTestimonial = (index) => {
    setDirection(index > currentTestimonial ? 'right' : 'left');
    setCurrentTestimonial(index);
  };

  return (
    <div className='bg-gradient-to-br from-gray-900 via-slate-800 to-[#051A3A] min-h-screen'>
      {/* Testimonials Section */}
      <div className="pt-16 max-w-6xl mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-4xl max-sm:text-3xl font-bold text-white mb-4">
            What Our <span className="text-[#F6C343]">Clients Say</span>
          </h2>
          <div className="w-32 h-1 bg-gradient-to-r from-[#F6C343] to-[#e3ae25] mx-auto rounded-full"></div>
        </div>
        
        <div className="bg-gradient-to-br from-gray-800/40 to-[#051A3A]/20 rounded-3xl p-8 backdrop-blur-sm border border-[#F6C343]/20 shadow-2xl">
          {/* Main Testimonial Card */}
          <div className="relative h-96 overflow-hidden">
            {testimonials.map((testimonial, index) => (
              <div
                key={index}
                className={`absolute inset-0 transition-all duration-500 ease-in-out ${
                  index === currentTestimonial
                    ? 'opacity-100 translate-x-0'
                    : direction === 'right'
                      ? index < currentTestimonial
                        ? '-translate-x-full opacity-0'
                        : 'translate-x-full opacity-0'
                      : index > currentTestimonial
                        ? 'translate-x-full opacity-0'
                        : '-translate-x-full opacity-0'
                }`}
              >
                <div className="bg-gradient-to-br from-gray-700/30 to-[#051A3A]/20 p-8 rounded-2xl border border-[#F6C343]/10 h-full">
                  <div className="text-center h-full flex flex-col justify-center">
                    <div className="text-6xl text-[#F6C343] mb-4">"</div>
                    <p className="text-gray-300 text-lg leading-relaxed italic mb-6">
                      {testimonial.text}
                    </p>
                    <div className="text-center">
                      <h4 className="text-xl font-bold text-[#F6C343]">
                        {testimonial.name}
                      </h4>
                      <p className="text-gray-400">
                        {testimonial.location}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Navigation Controls */}
          <div className="flex justify-center items-center space-x-4 mt-8">
            <button
              onClick={prevTestimonial}
              className="bg-gradient-to-r from-[#F6C343] to-[#e3ae25] hover:from-[#F6C343] hover:to-[#051A3A] p-3 rounded-full text-white shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-300"
              aria-label="Previous testimonial"
            >
              <ChevronLeft size={20} />
            </button>
            
            <div className="flex space-x-2">
              {testimonials.map((_, index) => (
                <button
                  key={index}
                  onClick={() => goToTestimonial(index)}
                  className={`w-3 h-3 rounded-full transition-all duration-300 ${
                    index === currentTestimonial
                      ? 'bg-gradient-to-r from-[#F6C343] to-[#e3ae25] scale-125'
                      : 'bg-gray-600 hover:bg-gray-500'
                  }`}
                  aria-label={`Go to testimonial ${index + 1}`}
                />
              ))}
            </div>
            
            <button
              onClick={nextTestimonial}
              className="bg-gradient-to-r from-[#F6C343] to-[#e3ae25] hover:from-[#F6C343] hover:to-[#051A3A] p-3 rounded-full text-white shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-300"
              aria-label="Next testimonial"
            >
              <ChevronRight size={20} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useState, useEffect } from "react";
import govtApprovedProject from "@/app/assets/home/govt-approved-project.webp";
import salesDeed from "@/app/assets/home/immediate-sale-deed.webp";
import afterSales from "@/app/assets/home/after-sales.webp";
import buybackguarantee from "@/app/assets/home/buy-back-guarantee.webp";
import location from "@/app/assets/home/location.webp";
import hidden from "@/app/assets/home/hiddenCharges.webp";
import Image from "next/image";
import projectImage from "@/app/assets/home/westwyn-project.webp";
import bg from "@/app/assets/home/pexels2.jpg";

const features = [
  {
    icon: govtApprovedProject,
    title: "Govt Approved Projects",
    description: "Fully government approved and verified",
  },
  {
    icon: salesDeed,
    title: "Immediate Sale Deed",
    description: "Quick documentation and registration",
  },
  {
    icon: afterSales,
    title: "After Sales Support",
    description: "Comprehensive post-purchase assistance",
  },
  {
    icon: hidden,
    title: "Transparent Pricing",
    description: "No hidden charges, clear pricing structure",
  },
  {
    icon: buybackguarantee,
    title: "Buy Back Guarantee",
    description: "*Terms & Conditions Apply*",
  },
];

export default function Westwyn() {
  const [investmentYear, setInvestmentYear] = useState(5);
  const [plotSize, setPlotSize] = useState(200);
  const [customYear, setCustomYear] = useState("");

  const baseRate = 9250; // Current price per sq. yard
  const targetRate = 17000; // Price after 5 years
  const annualGrowthRate = 0.05; // 5% annual growth

  const calculateFutureValue = (years) => {
    // If years is 2 or less, use linear interpolation to match exactly 13000 at 2 years
    if (years <= 5) {
      const incrementPerYear = (targetRate - baseRate) / 5;
      return baseRate + incrementPerYear * years;
    } else {
      // For years > 2, use compound growth at 5% from the 2-year mark
      return targetRate * Math.pow(1 + annualGrowthRate, years - 5);
    }
  };

  const calculateInvestment = () => {
    let years = investmentYear;
    if (customYear) {
      years = parseInt(customYear);
    }

    const futureRate = calculateFutureValue(years);
    const currentInvestment = baseRate * plotSize;
    const futureValue = futureRate * plotSize;
    const profit = futureValue - currentInvestment;
    const percentageGrowth = (futureValue / currentInvestment - 1) * 100;

    return {
      currentValue: currentInvestment,
      futureValue: futureValue,
      profit: profit,
      percentageGrowth: percentageGrowth,
      ratePerSqYard: futureRate,
    };
  };

  const investmentDetails = calculateInvestment();

  useEffect(() => {
    // Initialize animation observers when component mounts
    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("animate-visible");
          observer.unobserve(entry.target);
        }
      });
    }, observerOptions);

    // Observe all animation elements
    document
      .querySelectorAll(
        ".fade-in-up, .feature-item, .project-image, .amenity-item, .investment-calculator"
      )
      .forEach((el) => observer.observe(el));

    return () => {
      observer.disconnect();
      // Ensure we clean up by enabling scrolling when component unmounts
      document.body.style.overflow = "auto";
    };
  }, []);

  return (
    <>
      <style jsx global>
        {`
          /* Fade in animation */
          .fade-in-up {
            opacity: 0;
            transform: translateY(30px);
            transition:
              opacity 0.6s ease,
              transform 0.6s ease;
          }

          .fade-in-up.animate-visible {
            opacity: 1;
            transform: translateY(0);
          }

          /* Staggered animation for feature items */
          .feature-item,
          .amenity-item {
            opacity: 0;
            transform: translateX(-30px);
            transition:
              opacity 0.5s ease,
              transform 0.5s ease;
          }

          .feature-item.animate-visible,
          .amenity-item.animate-visible {
            opacity: 1;
            transform: translateX(0);
          }

          .feature-item:nth-child(1),
          .amenity-item:nth-child(1) {
            transition-delay: 0.1s;
          }
          .feature-item:nth-child(2),
          .amenity-item:nth-child(2) {
            transition-delay: 0.2s;
          }
          .feature-item:nth-child(3),
          .amenity-item:nth-child(3) {
            transition-delay: 0.3s;
          }
          .feature-item:nth-child(4),
          .amenity-item:nth-child(4) {
            transition-delay: 0.4s;
          }
          .feature-item:nth-child(5) {
            transition-delay: 0.5s;
          }
          .feature-item:nth-child(6) {
            transition-delay: 0.6s;
          }

          /* Project image animation */
          .project-image {
            opacity: 0;
            transform: translateX(50px);
            transition:
              opacity 0.8s ease,
              transform 0.8s ease;
          }

          .project-image.animate-visible {
            opacity: 1;
            transform: translateX(0);
          }

          /* Calculator animation */
          .investment-calculator {
            opacity: 0;
            transform: translateY(30px);
            transition:
              opacity 0.8s ease,
              transform 0.8s ease;
            transition-delay: 0.3s;
          }

          .investment-calculator.animate-visible {
            opacity: 1;
            transform: translateY(0);
          }

          /* Modal styles */
          .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0, 0, 0, 0.7);
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 1000;
            padding: 1rem;
          }

          .modal-content {
            background: linear-gradient(
              135deg,
              #1f2937 0%,
              #374151 50%,
              #051A3A 100%
            );
            border-radius: 0.5rem;
            width: 100%;
            max-width: 500px;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
            border: 1px solid rgba(246, 195, 67, 0.2);
          }

          /* Add spacing between sections */
          .westwyn-container section {
            margin-bottom: 5rem;
          }

          /* Glass morphism effect for feature cards */
          .westwyn-feature-card {
            background: rgba(255, 255, 255, 0.1);
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.2);
            transition: all 0.3s ease;
          }

          .westwyn-feature-card:hover {
            background: rgba(255, 255, 255, 0.15);
            transform: translateY(-2px);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
          }

          /* Floating card enhancement */
          .westwyn-floating-card {
            background: linear-gradient(
              135deg,
              rgba(255, 255, 255, 0.9) 0%,
              rgba(255, 255, 255, 0.8) 100%
            );
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.3);
          }
        `}
      </style>

      <div
        id="westwyn-county"
        className="westwyn-container relative overflow-hidden"
      >
