                <div className="text-gray-200 text-sm">Sq. Yards Plots</div>
              </div>
              <div className="mb-2">
                <div className="text-3xl font-bold bg-gradient-to-r from-[#F6C343] to-[#e3ae25] bg-clip-text text-transparent text-center drop-shadow-lg">
