import React, { useState } from 'react';
import Link from 'next/link';

export default function About() {
  const [activeDropdown, setActiveDropdown] = useState(null);

  const toggleDropdown = (index) => {
    setActiveDropdown(activeDropdown === index ? null : index);
  };

  const reasons = [
    {
      title: "Price Appreciation",
      content: "As development moves forward, the land value in Dholera is increasing year by year. Those who invest early can benefit from significant price growth in the future. Dholera Smart City is still in its early phase — perfect timing for smart buyers."
    },
    {
      title: "Rental Income",
      content: "As businesses, industries, and families start moving into Dholera Smart City, the demand for homes and commercial spaces will grow. This means you can earn steady rental income from your investment, whether it's a plot, shop, or home."
    },
    {
      title: "Government-Backed Development",
      content: "Dholera Smart City is fully supported by both the Central and Gujarat State Governments. It is part of the Delhi-Mumbai Industrial Corridor (DMIC) and is managed by a dedicated authority (DSIRDA). This ensures fast, planned, and safe development."
    },
    {
      title: "Early Mover Advantage",
      content: "Right now, property prices are much lower compared to what they will be in the next 5–10 years. Investing early gives you access to the best locations and highest returns before the city becomes fully developed."
    },
    {
      title: "Industrial Growth Hub",
      content: "Dholera is designed to be a global industrial and economic zone. Companies in sectors like renewable energy, manufacturing, logistics, and IT are already showing interest. As industries set up here, job creation and demand for housing will grow rapidly."
    }
  ];

  return (
    <div className='bg-gradient-to-br from-gray-900 via-slate-800 to-[#051A3A] min-h-screen pb-8'>
      {/* Why Dholera Smart City Section */}
      <div className="pt-16 max-w-6xl mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-4xl max-sm:text-3xl font-bold text-white mb-4">
            Why <span className="text-[#F6C343]">Dholera Smart City</span>?
          </h2>
          <div className="w-32 h-1 bg-gradient-to-r from-[#F6C343] to-[#e3ae25] mx-auto rounded-full"></div>
        </div>

        <div className="bg-gradient-to-br from-gray-800/40 to-[#051A3A]/20 rounded-3xl p-8 backdrop-blur-sm border border-[#F6C343]/20 shadow-2xl">
          <p className="text-gray-300 text-lg leading-relaxed mb-8 text-center">
            <span className="font-bold text-[#F6C343]">Dholera Smart City</span> is not just a plan — it's a powerful opportunity.
            Backed by the government and built with world-class infrastructure, this futuristic city is attracting investors
            from across India and abroad. Here's why smart investors are choosing Dholera:
          </p>

          <div className="space-y-3 mt-8">
            {reasons.map((reason, index) => (
              <div
                key={index}
                className="bg-gradient-to-br from-gray-700/30 to-[#051A3A]/20 rounded-2xl border border-[#F6C343]/10 transition-all duration-300 overflow-hidden hover:border-[#F6C343]/30"
              >
                <button
                  onClick={() => toggleDropdown(index)}
                  className="w-full flex items-center justify-between p-6 text-left focus:outline-none"
                >
                  <div className="flex items-center">
                    <div className="w-8 h-8 bg-gradient-to-r from-[#F6C343] to-[#e3ae25] rounded-full flex items-center justify-center text-white font-bold text-sm mr-3">
                      {index + 1}
                    </div>
                    <h3 className="text-xl font-bold text-[#F6C343]">{reason.title}</h3>
                  </div>
                  <svg
                    className={`w-6 h-6 text-[#F6C343] transition-transform duration-300 ${
                      activeDropdown === index ? 'transform rotate-180' : ''
                    }`}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    xmlns="http://www.w3.org/2000/svg"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M19 9l-7 7-7-7"
                    />
                  </svg>
                </button>
                <div
                  className={`transition-all duration-500 ease-in-out overflow-hidden ${
                    activeDropdown === index
                      ? 'max-h-96 opacity-100'
                      : 'max-h-0 opacity-0'
                  }`}
                >
                  <div className="px-6 pb-6">
                    <p className="text-gray-300 leading-relaxed pl-11">
                      {reason.content}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Learn More Button */}
          <div className="flex justify-center mt-12">
            <Link href="/inside-dholera">
              <button className="bg-gradient-to-r from-[#F6C343] to-[#e3ae25] hover:from-[#F6C343] hover:to-[#051A3A] px-8 py-3 rounded-full text-white font-semibold text-lg shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-300">
                Learn More
              </button>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client"
import React, { useState, useEffect } from 'react';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import icon from "@/app/assets/images/pdfIcon.webp"
import InternationalPhoneInput, { getInternationalPhoneValue } from "./InternationalPhoneInput";

function formatIndianNumber(value) {
  return parseFloat(value).toLocaleString('en-IN', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

export default function CostSheet() {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    plotNo: '',
    plc: '',
    plotAreaYards: '',
    basePlotPriceYards: 9250, 
    plotAreaFeet: '',
    totalPaymentYards: '',
    maintenanceRate: 500, 
    maintenanceCharge: 0,
    legalFees: 20000,
    oneTimeMaintenance: 50000, 
    totalCharges: 0,
    plotTotalPayment: 0,
  });

  const plotPriceWithPLC = parseFloat(formData.basePlotPriceYards) + (parseFloat(formData.plc) || 0);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  useEffect(() => {
    if (formData.plotAreaYards && formData.basePlotPriceYards) {
      const plotPrice = plotPriceWithPLC;
      const totalPayment = formData.plotAreaYards * plotPrice;
      const legalFees = parseFloat(formData.legalFees) || 0;
      const oneTimeMaintenance = parseFloat(formData.oneTimeMaintenance) || 0;
      const maintenance = formData.plotAreaYards * formData.maintenanceRate; 
      const totalCharges = maintenance + legalFees + oneTimeMaintenance;
      const plotTotalPayment = totalPayment + totalCharges;
      const plotAreaFeet = formData.plotAreaYards * 9;
  
      setFormData(prevData => ({
        ...prevData,
        plotAreaFeet,
        totalPaymentYards: totalPayment.toFixed(2),
        maintenanceCharge: maintenance.toFixed(2),
        totalCharges: totalCharges.toFixed(2),
        plotTotalPayment: plotTotalPayment.toFixed(2),
      }));
    }
  }, [formData.plotAreaYards, formData.basePlotPriceYards, formData.plc, formData.maintenanceRate, formData.legalFees, formData.oneTimeMaintenance]);

  const generatePDF = () => {
    const doc = new jsPDF();

    const { name, phone, email, plc, plotNo, plotAreaYards, plotAreaFeet, totalPaymentYards, maintenanceRate, maintenanceCharge, legalFees, oneTimeMaintenance, totalCharges, plotTotalPayment } = formData;
    const formattedPhone = getInternationalPhoneValue(phone);

    let startY = 40;

    const img = new Image();
    img.src = icon.src;
    img.crossOrigin = "anonymous";

    img.onload = () => {
      doc.addImage(img, "WEBP",  5, 5, 185, 38);
      doc.setFontSize(16);
      doc.setFont('helvetica', 'bold');
      let pageWidth = doc.internal.pageSize.getWidth();
      const head = document.querySelector("h1")?.innerText || "Cost Sheet";
      let text = doc.getTextWidth(head);
      let xPosition = (pageWidth - text) / 2;
      doc.text(head, xPosition, 48);

      startY += 10;

      // Format Indian Numbers
      const formattedplc = formatIndianNumber(plc);
      const formattedPricePerYard = formatIndianNumber(plotPriceWithPLC);
      const formattedTotalPaymentYards = formatIndianNumber(totalPaymentYards);
      const formattedMaintenanceCharge = formatIndianNumber(maintenanceCharge);
      const formattedLegalFees = formatIndianNumber(legalFees);
      const formattedOneTimeMaintenance = formatIndianNumber(oneTimeMaintenance);
      const formattedTotalCharges = formatIndianNumber(totalCharges);
      const formattedPlotTotalPayment = formatIndianNumber(plotTotalPayment);

      // Table with details
      autoTable(doc,{
        startY: startY,
        body: [
          ['Name', name],
          ['Phone', formattedPhone],
          ['Email', email],
          ['PlotNo', plotNo],
          ['Plot Area (Sq. Yards)', plotAreaYards],
          ['Plot Area (Sq. Feet)', plotAreaFeet],
          ['Plot Price per Sq. Yard', `Rs. ${formatIndianNumber(formData.basePlotPriceYards)}`],
          ['Preffered Location Charges (PLC)', `Rs. ${formattedplc}`],
          ['Final Plot Price per Sq. Yard', `Rs. ${formattedPricePerYard}`],
          ['Total Payment', `Rs. ${formattedTotalPaymentYards}`],
        ],
        theme: 'grid',
        styles: { fontSize: 12, cellPadding: 3, lineWidth: 0.5, lineColor: [0, 0, 0] },
        headStyles: { fillColor: [0, 51, 102], textColor: 255, fontStyle: 'bold', lineWidth: 0.8 },
        alternateRowStyles: { fillColor: [225, 230, 255] },
        columnStyles: {
          0: { halign: 'left', cellWidth: 'auto' },
          1: { halign: 'right', cellWidth: 80 }
        }
      });

      let finalY = doc.lastAutoTable.finalY + 6;

      // Additional Charges Heading
      doc.setFontSize(14);
      doc.text('Additional Charges', pageWidth / 2, finalY, { align: "center" });

      // Table for Additional Charges
      autoTable(doc,{
        startY: finalY + 4,
        body: [
          [`Development Charge (${maintenanceRate} x Size)`, `Rs. ${formattedMaintenanceCharge}`],
          ['Legal Fee (Per Sale Deed)', `Rs. ${formattedLegalFees}`],
          ['Maintenance For 3 years', `Rs. ${formattedOneTimeMaintenance}`],
          ['Total Charges', `Rs. ${formattedTotalCharges}`],
          ['Plot Total Payment', `Rs. ${formattedPlotTotalPayment}`],
        ],
        theme: "grid",
        styles: { fontSize: 12, cellPadding: 3, lineWidth: 0.5, lineColor: [0, 0, 0] },
        headStyles: { fillColor: [0, 51, 102], textColor: 255, fontStyle: "bold", lineWidth: 0.8 },
        alternateRowStyles: { fillColor: [225, 230, 255] },
        columnStyles: {
            0: { halign: 'left', cellWidth: 'auto' },
            1: { halign: 'right', cellWidth: 80 }
        }
      });

      finalY = doc.lastAutoTable.finalY;

      // Terms & Conditions Section
      doc.setFontSize(10);
      doc.text('Terms & Conditions:', 15, finalY + 8);
      doc.setFontSize(9);
      const terms = [
        "1. The booking amount is Rs. 50,000.",
        "2. You can request a refund within 30 days, and the payment will be returned to you within 7 days.",
        "3. This is a system-generated document and does not require a signature.",
        "4. The plot price and charges are subject to change without prior notice.",
        "5. Maintenance charges are one-time and non-refundable.",
        "6. Legal fees cover documentation and registration expenses.",
        "7. The final payment must be completed within the stipulated period.",
        "8. Full payment is to be completed within 30 days.",
        "9. For registry, stamp duty is 4.9% for females and 5.9% for males.",
        "10. Preferred Location Charge (PLC) will be added where necessary."
      ];

      terms.forEach((term, index) => {
        doc.text(term, 15, finalY + 18 + index * 5);
      });

      // Date of Generation
      let date = new Date().toLocaleDateString();
      doc.setFontSize(9);
      doc.text(`Date of Generation: ${date}`, 15, doc.internal.pageSize.height - 5);

      // Save PDF
      doc.save('Plot_Details.pdf');
    };

    img.onerror = () => {
      console.error("Error loading image.");
    };
  };

  return (
    <div className="max-w-3xl mx-auto bg-[#051A3A] shadow-xl shadow-gray-500 rounded-lg p-6 mt-10 border border-[#F6C343]">
      <p className="text-center text-3xl font-bold text-white mb-4">Plot Price Calculation</p>
      <form>
        <table className="w-full border-collapse overflow-hidden rounded-lg bg-[#FDFCFA] text-[#162033]">
          <tbody>
            {/* Name */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Name</td>
              <td className="p-2">
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>
            {/* Phone Number */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Phone Number</td>
              <td className="p-2">
                <InternationalPhoneInput
                  value={formData.phone}
                  onChange={(phone) =>
                    setFormData((prevData) => ({ ...prevData, phone }))
                  }
                  inputClass="!w-full !h-[42px] !rounded !border !border-[#2B364D] !bg-[#FDFCFA] !py-2 !pl-14 !pr-2 !text-[#162033] placeholder:!text-[#6C7484] focus:!outline-none focus:!ring-2 focus:!ring-[#F6C343]"
                  buttonClass="!rounded-l !border !border-[#2B364D] !bg-[#FDFCFA] hover:!bg-[#FDFCFA]"
                  inputProps={{
                    id: "phone",
                    name: "phone",
                  }}
                />
              </td>
            </tr>
            {/* Email */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Email</td>
              <td className="p-2">
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>
            {/* Plot No */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Plot No</td>
              <td className="p-2">
                <input
                  type="text"
                  name="plotNo"
                  value={formData.plotNo}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>
            {/* PLC */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Preferred Location Charge (PLC)</td>
              <td className="p-2">
                <input
                  type="number"
                  name="plc"
                  value={formData.plc}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>
            {/* Plot Area */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Plot Area (Sq. Yards)</td>
              <td className="p-2">
                <input
                  type="number"
                  name="plotAreaYards"
                  value={formData.plotAreaYards}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>
            {/* Plot Area (Feet) */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Plot Area (Sq. Feet)</td>
              <td className="p-2">
                <input
                  type="number"
                  name="plotAreaFeet"
                  value={formData.plotAreaFeet}
                  className="border p-2 w-full rounded"
                  readOnly
                />
              </td>
            </tr>
            {/* Base Plot Price per Yard */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Base Plot Price per Sq. Yard</td>
              <td className="p-2">
                <input
                  type="number"
                  name="basePlotPriceYards"
                  value={formData.basePlotPriceYards}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>
            {/* Final Plot Price per Yard (calculated) */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Final Plot Price per Sq. Yard (Base + PLC)</td>
              <td className="p-2">
                <input
                  type="text"
                  value={plotPriceWithPLC.toFixed(2)}
                  className="border p-2 w-full rounded"
                  readOnly
                />
              </td>
            </tr>
            {/* Total Payment */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Total Payment</td>
              <td className="p-2">
                <input
                  type="text"
                  name="totalPaymentYards"
                  value={formData.totalPaymentYards}
                  className="border p-2 w-full rounded"
                  readOnly
                />
              </td>
            </tr>

            {/* Additional Charges Section */}
            <tr className="border-b bg-gray-100">
              <td colSpan="2" className="p-2 font-bold text-center">Additional Charges</td>
            </tr>

            {/* Maintenance Charge Rate Dropdown */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Maintenance Charge Rate</td>
              <td className="p-2">
                <select
                  name="maintenanceRate"
                  value={formData.maintenanceRate}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                >
                  <option value="100">100</option>
                  <option value="500">500</option>
                </select>
              </td>
            </tr>

            {/* Maintenance Charge */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Maintenance Charge ({formData.maintenanceRate} x Size)</td>
              <td className="p-2">
                <input
                  type="text"
                  value={formData.maintenanceCharge}
                  className="border p-2 w-full rounded"
                  readOnly
                />
              </td>
            </tr>

            {/* Legal Fee - Now Editable */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Legal Fee (Per Sale Deed)</td>
              <td className="p-2">
                <input
                  type="number"
                  name="legalFees"
                  value={formData.legalFees}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>

            {/* One Time Maintenance - Now Editable */}
            <tr className="border-b">
              <td className="p-2 font-semibold">One Time Maintenance(for 3 years)</td>
              <td className="p-2">
                <input
                  type="number"
                  name="oneTimeMaintenance"
                  value={formData.oneTimeMaintenance}
                  onChange={handleChange}
                  className="border p-2 w-full rounded"
                />
              </td>
            </tr>

            {/* Total Charges */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Total Charges</td>
              <td className="p-2">
                <input
                  type="text"
                  value={formData.totalCharges}
                  className="border p-2 w-full rounded"
                  readOnly
                />
              </td>
            </tr>

            {/* Plot Total Payment */}
            <tr className="border-b">
              <td className="p-2 font-semibold">Plot Total Payment</td>
              <td className="p-2">
                <input
                  type="text"
                  value={formData.plotTotalPayment}
                  className="border p-2 w-full rounded"
                  readOnly
                />
              </td>
            </tr>
          </tbody>
        </table>

        <button
          type="button"
          onClick={generatePDF}
          className="bg-[#F6C343] text-[#051A3A] font-bold p-2 mt-6 w-full rounded hover:bg-[#FDFCFA] transition-colors"
        >
          Generate PDF
        </button>
      </form>
    </div>
  );
}

