              <div className="relative w-full aspect-video md:aspect-[16/9] lg:aspect-[21/9]">
                <iframe
                  src={location.mapSrc}
                  className="absolute top-0 left-0 w-full h-full border-0"
                  allowFullScreen
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
